import { House, ListBullets, Gear } from "@phosphor-icons/react";
import { useNavigate, useLocation } from "react-router-dom";

interface NavItem {
  label: string;
  icon: (active: boolean) => React.ReactNode;
  path: string;
}

const navItems: NavItem[] = [
  {
    label: "Início",
    path: "/dashboard",
    icon: (active) => <House size={24} weight={active ? "fill" : "regular"} />,
  },
  {
    label: "Extrato",
    path: "/extrato",
    icon: (active) => (
      <ListBullets size={24} weight={active ? "fill" : "regular"} />
    ),
  },
  {
    label: "Chaves",
    path: "/chaves",
    icon: (active) =>
      active ? <PixFillIcon size={24} /> : <PixRegularIcon size={24} />,
  },
  {
    label: "Ajustes",
    path: "/ajustes",
    icon: (active) => <Gear size={24} weight={active ? "fill" : "regular"} />,
  },
];

export function BottomNav() {
  const navigate = useNavigate();
  const { pathname } = useLocation();

  // normaliza trailing slash para a comparação não falhar em modo export do Next.js
  const currentPath = pathname.replace(/\/$/, '') || '/';

  return (
    <nav
      className="fixed bottom-0 left-1/2 -translate-x-1/2 w-full max-w-md
        border-t border-bg-input bg-bg z-50"
      aria-label="Navegação principal"
    >
      <div className="grid grid-cols-4 py-2">
        {navItems.map((item) => {
          const isActive = currentPath === item.path;
          return (
            <button
              key={item.label}
              onClick={() => navigate(item.path)}
              aria-label={item.label}
              aria-current={isActive ? "page" : undefined}
              className={`flex flex-col items-center gap-1 py-2 transition-colors
                ${isActive ? "text-brand-element" : "text-text-secondary"}
                hover:text-text active:scale-95`}
            >
              {item.icon(isActive)}
              <span className="text-[10px] font-medium">{item.label}</span>
            </button>
          );
        })}
      </div>
    </nav>
  );
}
